namespace Fabric.Cli.Tests;

/// <summary>
/// <c>fabric change</c> (ADR-0016 C1 to C3, #720): a project generated by this build from the real catalog and packs, in
/// the default colour scheme (blue), committed, edited outside the palettes, and changed to orange. The change merges
/// what this fabric writes for the changed choices into the project, three-way against what it writes for the recorded
/// ones; a choice the catalog does not mark changeable is refused before anything is touched.
/// </summary>
public sealed class ChangeCommandTests : IDisposable
{
    private const string Profile = "lean-crud";

    private const string Styles = "web/app/src/index.css";

    private const string OwnNotes = "Our own notes.\n";

    private readonly string root = Directory.CreateTempSubdirectory("fabric-change-").FullName;

    private readonly string project;

    public ChangeCommandTests()
    {
        project = Path.Combine(root, "shop");
        New(project).ExitCode.ShouldBe(0);
        Git.Run(project, "init", "-q");
        Git.Commit(project, "generate");
    }

    public void Dispose() => Directory.Delete(root, recursive: true);

    [Fact]
    public void A_project_changed_from_blue_to_orange_is_repainted_records_orange_and_keeps_an_edit_elsewhere()
    {
        Read(Styles).ShouldContain("--primary: oklch(0.488 0.243 264.376);");
        Write("README.md", Read("README.md") + OwnNotes);
        Git.Commit(project, "our notes");

        var run = Change("--set", "frontend.color-scheme=orange");

        run.ExitCode.ShouldBe(0, run.Error);
        run.Output.ShouldStartWith("changed shop's frontend.color-scheme from blue to orange; nothing is committed.");
        run.Output.ShouldContain($"  M {Styles}");
        run.Output.ShouldContain("  M fabric.yaml");
        run.Output.ShouldNotContain("conflict");
        Git.Run(project, "ls-files", "-u").ShouldBeEmpty();

        var styles = Read(Styles);
        Block(styles, ":root").ShouldContain("--primary: oklch(0.553 0.195 38.402);");
        Block(styles, ".dark").ShouldContain("--primary: oklch(0.47 0.157 37.304);");
        styles.ShouldNotContain("264.376");
        Read("fabric.yaml").ShouldContain("\n  frontend.color-scheme: orange\n", Case.Sensitive);
        Read("README.md").ShouldEndWith(OwnNotes);

        var fresh = Fresh("--set", "frontend.color-scheme=orange");
        fresh["README.md"] += OwnNotes;
        Tree(project).ShouldBe(fresh);
    }

    [Fact]
    public void A_project_changed_from_inter_to_geist_imports_and_names_geist_and_keeps_an_edit_elsewhere()
    {
        Read(Styles).ShouldContain("@import '@fontsource-variable/inter';");
        Write("README.md", Read("README.md") + OwnNotes);
        Git.Commit(project, "our notes");

        var run = Change("--set", "frontend.font=geist");

        run.ExitCode.ShouldBe(0, run.Error);
        run.Output.ShouldStartWith("changed shop's frontend.font from inter to geist; nothing is committed.");
        run.Output.ShouldContain($"  M {Styles}");
        run.Output.ShouldContain("  M web/app/package.json");
        run.Output.ShouldNotContain("conflict");
        Git.Run(project, "ls-files", "-u").ShouldBeEmpty();

        var styles = Read(Styles);
        styles.ShouldContain("@import '@fontsource-variable/geist';");
        styles.ShouldContain("--font-sans: 'Geist Variable',");
        styles.ShouldNotContain("@fontsource-variable/inter");
        styles.ShouldNotContain("'Inter Variable'");
        Read("web/app/package.json").ShouldContain("\"@fontsource-variable/geist\":");
        Read("fabric.yaml").ShouldContain("\n  frontend.font: geist\n", Case.Sensitive);
        Read("README.md").ShouldEndWith(OwnNotes);

        var fresh = Fresh("--set", "frontend.font=geist");
        fresh["README.md"] += OwnNotes;
        Tree(project).ShouldBe(fresh);
    }

    [Fact]
    public void A_dimension_the_catalog_does_not_mark_changeable_is_refused_by_name_and_the_project_left_untouched()
    {
        var head = Git.Run(project, "rev-parse", "HEAD");
        var before = Tree(project);

        var run = Change("--set", "frontend.color-scheme=orange", "--set", "frontend.ui-library=radix-headless");

        run.ExitCode.ShouldBe(1);
        run.Output.ShouldBeEmpty();
        run.Error.ShouldContain(
            "frontend.ui-library cannot be changed after generation: the catalog does not mark it changeable (ADR-0016 C2).");
        run.Error.ShouldNotContain("frontend.color-scheme");
        Git.Run(project, "status", "--porcelain", "--untracked-files=all").ShouldBeEmpty();
        Git.Run(project, "rev-parse", "HEAD").ShouldBe(head);
        Tree(project).ShouldBe(before);
    }

    [Fact]
    public void A_project_another_fabric_wrote_is_refused_until_it_is_upgraded_and_left_untouched()
    {
        var fabricYaml = Read("fabric.yaml");
        var generatorLine = fabricYaml.Split('\n').Single(line => line.StartsWith("generator: ", StringComparison.Ordinal));
        Write("fabric.yaml", fabricYaml.Replace(generatorLine, "generator: 0.0.1", StringComparison.Ordinal));
        Git.Commit(project, "as if written by fabric 0.0.1");
        var head = Git.Run(project, "rev-parse", "HEAD");

        var run = Change("--set", "frontend.color-scheme=orange");

        run.ExitCode.ShouldBe(1);
        run.Error.ShouldContain($"fabric.yaml was written by fabric 0.0.1, not this fabric {generatorLine["generator: ".Length..]}; run fabric upgrade first");
        Git.Run(project, "status", "--porcelain", "--untracked-files=all").ShouldBeEmpty();
        Git.Run(project, "rev-parse", "HEAD").ShouldBe(head);
    }

    private static CliRun New(string directory, params string[] extra) =>
        CliRun.Of(["new", directory, "--profile", Profile, .. extra, "--catalog", Paths.RepositoryCatalog, "--packs", Paths.RepositoryPacks]);

    private CliRun Change(params string[] arguments) =>
        CliRun.Of(["change", "--project", project, .. arguments, "--catalog", Paths.RepositoryCatalog, "--packs", Paths.RepositoryPacks]);

    /// <summary>What this build writes from scratch for the changed choices: the tree an unedited project must change to.</summary>
    private Dictionary<string, string> Fresh(params string[] extra)
    {
        var fresh = Path.Combine(root, "fresh", "shop");
        New(fresh, extra).ExitCode.ShouldBe(0);
        return Tree(fresh);
    }

    private static Dictionary<string, string> Tree(string directory) =>
        Directory.EnumerateFiles(directory, "*", SearchOption.AllDirectories)
            .Select(file => Path.GetRelativePath(directory, file).Replace('\\', '/'))
            .Where(path => !path.StartsWith(".git/", StringComparison.Ordinal))
            .ToDictionary(path => path, path => File.ReadAllText(Path.Combine(directory, path)));

    /// <summary>The body of the first CSS block whose selector is <paramref name="selector"/>.</summary>
    private static string Block(string css, string selector)
    {
        var start = css.IndexOf(selector + " {", StringComparison.Ordinal);
        start.ShouldBeGreaterThanOrEqualTo(0, $"no {selector} block");
        return css[start..css.IndexOf('}', start)];
    }

    private string Read(string path) => File.ReadAllText(Path.Combine(project, path));

    private void Write(string path, string content) => File.WriteAllText(Path.Combine(project, path), content);
}
